python3 -c "
import json
for f in ['mmlu_paraphrases.json', 'arc_paraphrases.json', 'gsm8k_paraphrases.json']:
    try:
        data = json.load(open(f'/root/autodl-tmp/exp001/paraphrases/{f}'))
        if isinstance(data, list):
            print(f'{f}: {len(data)} items, keys={list(data[0].keys())}')
            qc_keys = [k for k in data[0].keys() if 'qc' in k.lower() or 'pass' in k.lower() or 'quality' in k.lower() or 'filter' in k.lower() or 'valid' in k.lower()]
            print(f'  QC-related fields: {qc_keys}')
            if qc_keys:
                for qk in qc_keys:
                    vals = set(str(d.get(qk)) for d in data[:20])
                    pass_count = sum(1 for d in data if d.get(qk))
                    print(f'  {qk}: pass={pass_count}/{len(data)} ({pass_count/len(data)*100:.1f}%), sample_vals={vals}')
            print(f'  sample item keys detail: {json.dumps({k: type(v).__name__ for k,v in data[0].items()}, indent=2)}')
        elif isinstance(data, dict):
            print(f'{f}: dict keys={list(data.keys())[:10]}')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"

